import{_ as o}from"./chunks/login.CvhJCXy5.js";import{_ as s,a as e}from"./chunks/payment.BU19hNYM.js";import{_ as n,C as i,o as l,c as d,a2 as r,E as h}from"./chunks/framework.DSc8fo6x.js";const P=JSON.parse('{"title":"Памятка кассира","description":"","frontmatter":{"pageClass":"print-compact"},"headers":[],"relativePath":"ru/kassir.md","filePath":"ru/kassir.md"}'),_={name:"ru/kassir.md"};function g(c,t,p,m,u,b){const a=i("KVideo");return l(),d("div",null,[t[0]||(t[0]=r('<h1 id="памятка-кассира" tabindex="-1">Памятка кассира <a class="header-anchor" href="#памятка-кассира" aria-label="Permalink to &quot;Памятка кассира&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Распечатайте эту страницу и положите рядом с кассой</p><p>В разделе <a href="./pdf.html">Скачать PDF</a> есть «Памятка кассира» — один лист A4.</p></div><h2 id="_1-как-открыть-программу" tabindex="-1">1. Как открыть программу <a class="header-anchor" href="#_1-как-открыть-программу" aria-label="Permalink to &quot;1. Как открыть программу&quot;">​</a></h2><p>Зелёный значок <strong>Kassa</strong> на рабочем столе → <strong>выберите своё имя</strong> → <strong>пароль</strong> → <strong>Войти</strong>.</p><p><img src="'+o+'" alt="Экран входа"></p><h2 id="_2-продажа" tabindex="-1">2. Продажа <a class="header-anchor" href="#_2-продажа" aria-label="Permalink to &quot;2. Продажа&quot;">​</a></h2><ol><li><strong>Отсканируйте штрихкод</strong> товара — товар попадает в корзину (звук «бип»). Если отсканировать тот же товар ещё раз, количество увеличится.</li><li>Если штрихкода нет — <strong>введите название</strong> в поле сверху и выберите товар из списка.</li><li>Весовой товар (кг) — введите вес, напр. <code>0,750</code>.</li><li>Изменить количество: <strong>−</strong> / <strong>+</strong>. Ошибочный товар удалите кнопкой <strong>✕</strong>.</li></ol><p><img src="'+s+'" alt="Экран продажи"></p>',8)),h(a,{name:"satis"}),t[1]||(t[1]=r('<h2 id="_3-оплата" tabindex="-1">3. Оплата <a class="header-anchor" href="#_3-оплата" aria-label="Permalink to &quot;3. Оплата&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Кнопка</th><th>Когда</th></tr></thead><tbody><tr><td><strong>Наличные</strong> или <strong>F2</strong></td><td>Введите сумму, которую дал покупатель (или кнопки 5 ₼, 10 ₼…). Программа покажет <strong>сдачу</strong>. Если сумма без сдачи — оставьте поле пустым.</td></tr><tr><td><strong>Карта</strong> или <strong>F3</strong></td><td>Сначала убедитесь, что оплата на банковском терминале прошла, потом подтвердите.</td></tr></tbody></table><p>Затем <strong>Завершить продажу</strong> или <strong>Enter</strong>.</p><p><img src="'+e+'" alt="Оплата наличными"></p><h2 id="_4-чек" tabindex="-1">4. Чек <a class="header-anchor" href="#_4-чек" aria-label="Permalink to &quot;4. Чек&quot;">​</a></h2><ul><li>Если подключён принтер чеков, чек <strong>печатается сам</strong>.</li><li>Если нет — после продажи нажмите кнопку <strong>«Чек»</strong> в зелёной надписи.</li></ul><h2 id="_5-звуки" tabindex="-1">5. Звуки <a class="header-anchor" href="#_5-звуки" aria-label="Permalink to &quot;5. Звуки&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Звук</th><th>Что значит</th></tr></thead><tbody><tr><td>Короткий «бип»</td><td>Товар найден</td></tr><tr><td>Низкий звук</td><td>Товар не найден — <strong>админ</strong> должен добавить товар в систему</td></tr></tbody></table><h2 id="_6-как-закрыть" tabindex="-1">6. Как закрыть <a class="header-anchor" href="#_6-как-закрыть" aria-label="Permalink to &quot;6. Как закрыть&quot;">​</a></h2><p><strong>✕</strong> в правом верхнем углу окна. Программа сама сделает бэкап и закроется. Если долго ничего не нажимать, программа выйдет из вашей учётной записи — введите пароль снова.</p><h2 id="если-что-то-не-получается" tabindex="-1">Если что-то не получается <a class="header-anchor" href="#если-что-то-не-получается" aria-label="Permalink to &quot;Если что-то не получается&quot;">​</a></h2><ul><li>Белый экран / «ошибка» — <strong>Перезагрузить</strong> или закройте окно и откройте снова. Продажи не пропадут.</li><li>Забыли пароль — <strong>админ</strong> меняет его в разделе «Пользователи».</li><li>Всё остальное — <a href="./problemler.html">Если что-то не получается</a>.</li></ul>',12))])}const x=n(_,[["render",g]]);export{P as __pageData,x as default};
